<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { ElMessage } from 'element-plus'
import { Camera, Plus, Tools } from '@element-plus/icons-vue'
import { api } from '@/api/client'
import type { Repair } from '@/types'
const repairs=ref<Repair[]>([]),loading=ref(true),dialogVisible=ref(false),submitting=ref(false),active=ref('全部')
const form=reactive({title:'',category:'水电维修',description:'',priority:'普通'})
const filtered=computed(()=>repairs.value.filter(i=>active.value==='全部'||i.status===active.value))
const steps=['待受理','已受理','维修中','已完成']
const statusClass=(s:string)=>({待受理:'wait',已受理:'accepted',维修中:'working',已完成:'done'}[s])
async function load(){loading.value=true;try{repairs.value=await api.get<Repair[]>('/api/student/repairs')}finally{loading.value=false}}
async function submit(){if(!form.title.trim()||!form.description.trim())return ElMessage.warning('请填写故障标题和详细描述');submitting.value=true;try{await api.post('/api/student/repairs',form);ElMessage.success('报修提交成功');dialogVisible.value=false;Object.assign(form,{title:'',category:'水电维修',description:'',priority:'普通'});await load()}catch(e){ElMessage.error(e instanceof Error?e.message:'提交失败')}finally{submitting.value=false}}
onMounted(load)
</script>
<template><div><div class="student-page-head"><div><span>REPAIR SERVICE</span><h1>在线报修</h1><p>提交宿舍设施问题，随时查看维修进度。</p></div><button @click="dialogVisible=true"><el-icon><Plus/></el-icon>提交报修</button></div><div class="service-note"><el-icon><Tools/></el-icon><div><strong>紧急问题请直接联系宿管值班室</strong><span>漏水、断电等紧急情况：138 0000 1201</span></div></div><section class="repair-layout"><aside class="repair-filter"><button v-for="tab in ['全部','待受理','已受理','维修中','已完成']" :key="tab" :class="{active:active===tab}" @click="active=tab"><span>{{tab}}</span><b>{{tab==='全部'?repairs.length:repairs.filter(i=>i.status===tab).length}}</b></button></aside><main v-loading="loading" class="repair-cards"><article v-for="item in filtered" :key="item.id"><header><div><span>{{item.category}}</span><strong>{{item.title}}</strong></div><b :class="statusClass(item.status)">{{item.status}}</b></header><div class="order-meta"><span>工单 {{item.orderNo}}</span><span>{{item.location}}</span><span>{{item.submittedAt}}</span></div><div class="timeline"><div v-for="(step,index) in steps" :key="step" :class="{active:index<=steps.indexOf(item.status),current:step===item.status}"><i/><span>{{step}}</span></div></div><footer><span v-if="item.status==='待受理'">宿管老师将在工作时间内尽快受理</span><span v-else-if="item.status==='已完成'">维修已完成，如有问题可重新报修</span><span v-else>维修人员正在跟进，请保持电话畅通</span><button>查看详情</button></footer></article><div v-if="!loading&&!filtered.length" class="empty-state"><el-icon><Tools/></el-icon><strong>暂无相关报修</strong><span>宿舍设施有问题时，可以在这里提交报修。</span></div></main></section><el-dialog v-model="dialogVisible" title="提交宿舍报修" width="min(540px,92vw)"><el-form label-position="top"><el-form-item label="报修类型"><el-select v-model="form.category"><el-option v-for="v in ['水电维修','空调维修','门窗维修','家具维修','网络故障','其他问题']" :key="v" :label="v" :value="v"/></el-select></el-form-item><el-form-item label="故障标题"><el-input v-model="form.title" maxlength="30" show-word-limit placeholder="简单描述出现的问题"/></el-form-item><el-form-item label="详细描述"><el-input v-model="form.description" type="textarea" :rows="4" maxlength="200" show-word-limit placeholder="请描述故障现象、出现时间等信息"/></el-form-item><el-form-item label="紧急程度"><el-radio-group v-model="form.priority"><el-radio value="普通">普通</el-radio><el-radio value="紧急">紧急</el-radio></el-radio-group></el-form-item><div class="upload-placeholder"><el-icon><Camera/></el-icon><span>上传故障照片</span><small>支持 JPG、PNG，最多 4 张（下一版本接入）</small></div></el-form><template #footer><el-button @click="dialogVisible=false">取消</el-button><el-button type="primary" :loading="submitting" @click="submit">确认提交</el-button></template></el-dialog></div></template>
<style scoped>.student-page-head{margin-bottom:20px;display:flex;align-items:end;justify-content:space-between}.student-page-head span{color:#198075;font-size:8px;letter-spacing:1.4px}.student-page-head h1{margin:5px 0;font-size:25px}.student-page-head p{margin:0;color:#82908c;font-size:11px}.student-page-head>button{height:38px;padding:0 14px;border:0;border-radius:8px;display:flex;align-items:center;gap:6px;color:white;background:#10786e;font-size:11px}.service-note{margin-bottom:16px;padding:13px 17px;border:1px solid #f1dfbf;border-radius:10px;display:flex;align-items:center;gap:11px;color:#a66f24;background:#fffaf0}.service-note>.el-icon{font-size:21px}.service-note div{display:grid;gap:3px}.service-note strong{font-size:10px}.service-note span{color:#af8b56;font-size:8px}.repair-layout{display:grid;grid-template-columns:150px 1fr;gap:16px}.repair-filter{height:max-content;padding:7px;border:1px solid #e1e7e4;border-radius:12px;display:grid;background:white}.repair-filter button{height:42px;padding:0 11px;border:0;border-radius:7px;display:flex;align-items:center;justify-content:space-between;color:#6f7d79;background:transparent;font-size:10px}.repair-filter button.active{color:#14766c;background:#eaf6f3;font-weight:600}.repair-filter b{font-size:9px;font-weight:500}.repair-cards{min-height:300px;display:grid;gap:11px}.repair-cards article{border:1px solid #e1e7e4;border-radius:13px;background:white}.repair-cards article header{padding:16px 19px;display:flex;align-items:center;justify-content:space-between}.repair-cards header>div{display:grid;gap:5px}.repair-cards header span{color:#84918d;font-size:8px}.repair-cards header strong{font-size:13px}.repair-cards header>b{padding:5px 9px;border-radius:12px;font-size:9px;font-weight:500}.wait{color:#bf654f;background:#fcedea}.accepted{color:#4a75a4;background:#edf3fa}.working{color:#ad7426;background:#fff2de}.done{color:#187b6b;background:#e8f5f1}.order-meta{padding:9px 19px;background:#fafbfb;display:flex;gap:24px;color:#84908d;font-size:8px}.timeline{padding:23px 30px 17px;display:flex}.timeline>div{position:relative;flex:1;display:grid;justify-items:center;gap:7px;color:#a1aaa7;font-size:8px}.timeline>div:before{content:'';position:absolute;top:5px;left:-50%;width:100%;height:2px;background:#e2e8e6}.timeline>div:first-child:before{display:none}.timeline i{width:11px;height:11px;z-index:1;border:2px solid #d4ddda;border-radius:50%;background:white}.timeline .active:before{background:#63bbae}.timeline .active i{border-color:#37a18f;background:#37a18f}.timeline .current span{color:#17766c;font-weight:600}.repair-cards footer{padding:11px 19px;border-top:1px solid #edf0ef;display:flex;justify-content:space-between;align-items:center;color:#8a9692;font-size:8px}.repair-cards footer button{border:0;color:#17766c;background:transparent;font-size:9px}.empty-state{min-height:300px;border:1px dashed #ced8d5;border-radius:13px;display:flex;flex-direction:column;align-items:center;justify-content:center;color:#96a19e}.empty-state>.el-icon{font-size:35px}.empty-state strong{margin:12px 0 5px;color:#687672;font-size:12px}.empty-state span{font-size:9px}.el-select{width:100%}.upload-placeholder{height:76px;border:1px dashed #ccd6d3;border-radius:8px;display:flex;align-items:center;justify-content:center;gap:8px;color:#6e7e7a;background:#fafcfc}.upload-placeholder span{font-size:10px}.upload-placeholder small{color:#a0aaa7;font-size:8px}@media(max-width:650px){.repair-layout{grid-template-columns:1fr}.repair-filter{display:flex;overflow-x:auto}.repair-filter button{min-width:76px}.order-meta{flex-wrap:wrap;gap:8px 16px}.timeline{padding-left:10px;padding-right:10px}}</style>
